// Package runtime installs the pinned compute runtime: a standalone
// CPython plus PyTorch wheels whose SHA-256 hashes are embedded in this
// reflopd build (lock.json, generated by codegen/lock_runtime.py). Only the
// Owner triggers installation (`reflopd up`, `reflopd runtime upgrade`).
package runtime

import (
	"archive/tar"
	"archive/zip"
	"compress/gzip"
	"context"
	"crypto/sha256"
	_ "embed"
	"encoding/hex"
	"encoding/json"
	"errors"
	"fmt"
	"io"
	"io/fs"
	"net/http"
	"os"
	"path"
	"path/filepath"
	goruntime "runtime"
	"sort"
	"strings"
	"time"

	"github.com/chaseungjoon/reflop/server"
	"github.com/chaseungjoon/reflop/server/reflopd/internal/gpu"
)

//go:embed lock.json
var lockJSON []byte

// Artifact is one pinned download.
type Artifact struct {
	Name    string `json:"name,omitempty"`
	Version string `json:"version,omitempty"`
	File    string `json:"file"`
	URL     string `json:"url"`
	SHA256  string `json:"sha256"`
}

// Variant is one runtime flavor (e.g. cu132).
type Variant struct {
	Torch     string                `json:"torch"`
	CUDA      string                `json:"cuda"`
	MinDriver string                `json:"min_driver"`
	MinCC     []int                 `json:"min_cc"`
	MaxCC     []int                 `json:"max_cc"`
	Wheels    map[string][]Artifact `json:"wheels"`
}

// Lock is the embedded lock file.
type Lock struct {
	Format int `json:"format"`
	Python struct {
		Release string   `json:"release"`
		Version string   `json:"version"`
		X8664   Artifact `json:"x86_64"`
		AArch64 Artifact `json:"aarch64"`
	} `json:"python"`
	Variants map[string]Variant `json:"variants"`
}

// Load parses the embedded lock.
func Load() (*Lock, error) {
	var l Lock
	if err := json.Unmarshal(lockJSON, &l); err != nil {
		return nil, err
	}
	if l.Format != 1 {
		return nil, fmt.Errorf("unsupported runtime lock format %d", l.Format)
	}
	return &l, nil
}

// Arch maps GOARCH to the wheel architecture name.
func Arch() (string, error) {
	switch goruntime.GOARCH {
	case "amd64":
		return "x86_64", nil
	case "arm64":
		return "aarch64", nil
	}
	return "", fmt.Errorf("unsupported architecture %s (reflopd supports amd64 and arm64)", goruntime.GOARCH)
}

// Choice is the selected variant and why.
type Choice struct {
	Variant string
	Reason  string
	Warn    []string
}

func parseDriver(s string) (int, int) {
	var a, b int
	fmt.Sscanf(s, "%d.%d", &a, &b)
	return a, b
}

func driverAtLeast(have, want string) bool {
	if want == "" {
		return true
	}
	ha, hb := parseDriver(have)
	wa, wb := parseDriver(want)
	return ha > wa || (ha == wa && hb >= wb)
}

func ccIn(maj, min int, lo, hi []int) bool {
	c := maj*10 + min
	if len(lo) == 2 && c < lo[0]*10+lo[1] {
		return false
	}
	if len(hi) == 2 && c > hi[0]*10+hi[1] {
		return false
	}
	return true
}

// Choose picks the runtime for this machine. Every exposed GPU must be
// supported by the variant; otherwise a lower variant (or CPU) is used.
func (l *Lock) Choose(inf gpu.Info, override string) (Choice, error) {
	if override != "" {
		if _, ok := l.Variants[override]; !ok {
			return Choice{}, fmt.Errorf("unknown runtime variant %q", override)
		}
		return Choice{Variant: override, Reason: "selected with --variant"}, nil
	}
	if len(inf.GPUs) == 0 || inf.Driver == "" {
		return Choice{Variant: "cpu", Reason: "no NVIDIA GPU or driver detected"}, nil
	}
	var warn []string
	for _, name := range []string{"cu132", "cu126"} {
		v := l.Variants[name]
		if !driverAtLeast(inf.Driver, v.MinDriver) {
			warn = append(warn, fmt.Sprintf("%s needs driver ≥ %s (have %s)", name, v.MinDriver, inf.Driver))
			continue
		}
		ok := true
		for _, g := range inf.GPUs {
			if g.CCMajor == 0 {
				continue // unknown: decided by the selftest
			}
			if !ccIn(g.CCMajor, g.CCMinor, v.MinCC, v.MaxCC) {
				ok = false
				warn = append(warn, fmt.Sprintf("%s does not support %s (compute capability %d.%d)", name, g.Name, g.CCMajor, g.CCMinor))
			}
		}
		if ok {
			return Choice{Variant: name, Reason: fmt.Sprintf("driver %s, CUDA %s", inf.Driver, v.CUDA), Warn: warn}, nil
		}
	}
	warn = append(warn, "falling back to the CPU runtime; update the NVIDIA driver to use the GPU")
	return Choice{Variant: "cpu", Reason: "no CUDA runtime matches this driver/GPU", Warn: warn}, nil
}

// ID names an installed runtime: variant plus a hash of its pinned bytes
// and of the embedded worker, so any change installs side by side.
func (l *Lock) ID(variant, arch string) string {
	h := sha256.New()
	py := l.python(arch)
	h.Write([]byte(py.SHA256))
	for _, w := range l.Variants[variant].Wheels[arch] {
		h.Write([]byte(w.SHA256))
	}
	_ = fs.WalkDir(server.Worker(), ".", func(p string, d fs.DirEntry, err error) error {
		if err == nil && !d.IsDir() && !strings.Contains(p, "__pycache__") {
			b, _ := fs.ReadFile(server.Worker(), p)
			h.Write([]byte(p))
			h.Write(b)
		}
		return nil
	})
	return fmt.Sprintf("%s-%s-%s", variant, arch, hex.EncodeToString(h.Sum(nil))[:12])
}

func (l *Lock) python(arch string) Artifact {
	if arch == "aarch64" {
		return l.Python.AArch64
	}
	return l.Python.X8664
}

// Marker is written when an installation is complete.
type Marker struct {
	ID        string    `json:"id"`
	Variant   string    `json:"variant"`
	Arch      string    `json:"arch"`
	Torch     string    `json:"torch"`
	CUDA      string    `json:"cuda"`
	Python    string    `json:"python"`
	Installed time.Time `json:"installed"`
}

// Installed describes a ready runtime.
type Installed struct {
	Dir    string
	Marker Marker
}

// PythonBin is the interpreter path.
func (i Installed) PythonBin() string { return filepath.Join(i.Dir, "python", "bin", "python3") }

// SitePackages is the site-packages dir.
func (i Installed) SitePackages(pyVersion string) string {
	mm := strings.Join(strings.Split(pyVersion, ".")[:2], ".")
	return filepath.Join(i.Dir, "python", "lib", "python"+mm, "site-packages")
}

// Find returns the installed runtime with id, if complete.
func Find(root, id string) (Installed, bool) {
	dir := filepath.Join(root, id)
	b, err := os.ReadFile(filepath.Join(dir, "READY.json"))
	if err != nil {
		return Installed{}, false
	}
	var m Marker
	if json.Unmarshal(b, &m) != nil || m.ID != id {
		return Installed{}, false
	}
	return Installed{Dir: dir, Marker: m}, true
}

// Progress receives human-readable progress lines.
type Progress func(format string, args ...any)

// Install downloads, verifies and unpacks the runtime. Downloads are
// cached under <root>/downloads by SHA-256, so retries resume cheaply.
func (l *Lock) Install(ctx context.Context, root, variant string, progress Progress) (Installed, error) {
	arch, err := Arch()
	if err != nil {
		return Installed{}, err
	}
	v, ok := l.Variants[variant]
	if !ok {
		return Installed{}, fmt.Errorf("unknown variant %q", variant)
	}
	id := l.ID(variant, arch)
	if inst, ok := Find(root, id); ok {
		return inst, nil
	}
	dl := filepath.Join(root, "downloads")
	if err := os.MkdirAll(dl, 0o700); err != nil {
		return Installed{}, err
	}
	arts := append([]Artifact{l.python(arch)}, v.Wheels[arch]...)
	for i, a := range arts {
		progress("[%d/%d] %s", i+1, len(arts), a.File)
		if err := fetch(ctx, a, dl); err != nil {
			return Installed{}, err
		}
	}
	tmp := filepath.Join(root, ".tmp-"+id)
	os.RemoveAll(tmp)
	if err := os.MkdirAll(tmp, 0o700); err != nil {
		return Installed{}, err
	}
	defer os.RemoveAll(tmp)
	progress("unpacking Python %s", l.Python.Version)
	if err := untarGz(filepath.Join(dl, arts[0].SHA256), tmp); err != nil {
		return Installed{}, fmt.Errorf("python: %w", err)
	}
	inst := Installed{Dir: tmp}
	site := inst.SitePackages(l.Python.Version)
	if err := os.MkdirAll(site, 0o755); err != nil {
		return Installed{}, err
	}
	for _, w := range v.Wheels[arch] {
		progress("installing %s", w.File)
		if err := unzipWheel(filepath.Join(dl, w.SHA256), site, filepath.Join(tmp, "python")); err != nil {
			return Installed{}, fmt.Errorf("%s: %w", w.File, err)
		}
	}
	progress("installing reflop_worker")
	if err := copyWorker(site); err != nil {
		return Installed{}, err
	}
	// Python must never write .pyc files into the runtime at run time.
	if err := os.WriteFile(filepath.Join(site, "reflop_runtime.pth"), []byte("import sys; sys.dont_write_bytecode = True\n"), 0o644); err != nil {
		return Installed{}, err
	}
	m := Marker{ID: id, Variant: variant, Arch: arch, Torch: v.Torch, CUDA: v.CUDA, Python: l.Python.Version, Installed: time.Now().UTC()}
	b, _ := json.MarshalIndent(m, "", "  ")
	if err := os.WriteFile(filepath.Join(tmp, "READY.json"), b, 0o644); err != nil {
		return Installed{}, err
	}
	if err := makeReadOnly(tmp); err != nil {
		return Installed{}, err
	}
	final := filepath.Join(root, id)
	os.RemoveAll(final)
	if err := os.Rename(tmp, final); err != nil {
		return Installed{}, err
	}
	return Installed{Dir: final, Marker: m}, nil
}

// List returns installed runtimes, newest first.
func List(root string) []Installed {
	ents, _ := os.ReadDir(root)
	var out []Installed
	for _, e := range ents {
		if inst, ok := Find(root, e.Name()); ok {
			out = append(out, inst)
		}
	}
	sort.Slice(out, func(i, j int) bool { return out[i].Marker.Installed.After(out[j].Marker.Installed) })
	return out
}

// Remove deletes an installed runtime directory.
func Remove(dir string) error {
	_ = filepath.WalkDir(dir, func(p string, d fs.DirEntry, err error) error {
		if err == nil && d.IsDir() {
			os.Chmod(p, 0o700)
		}
		return nil
	})
	return os.RemoveAll(dir)
}

var httpClient = &http.Client{Timeout: 0}

func fetch(ctx context.Context, a Artifact, dir string) error {
	dst := filepath.Join(dir, a.SHA256)
	if ok, _ := hashMatches(dst, a.SHA256); ok {
		return nil
	}
	part := dst + ".part"
	var lastErr error
	for attempt := 0; attempt < 5; attempt++ {
		if attempt > 0 {
			select {
			case <-ctx.Done():
				return ctx.Err()
			case <-time.After(time.Duration(attempt*attempt) * time.Second):
			}
		}
		lastErr = fetchOnce(ctx, a.URL, part)
		if lastErr == nil {
			break
		}
	}
	if lastErr != nil {
		return fmt.Errorf("download %s: %w", a.File, lastErr)
	}
	ok, got := hashMatches(part, a.SHA256)
	if !ok {
		os.Remove(part)
		return fmt.Errorf("checksum mismatch for %s: expected %s, got %s", a.File, a.SHA256, got)
	}
	return os.Rename(part, dst)
}

func fetchOnce(ctx context.Context, url, part string) error {
	f, err := os.OpenFile(part, os.O_CREATE|os.O_WRONLY, 0o600)
	if err != nil {
		return err
	}
	defer f.Close()
	off, _ := f.Seek(0, io.SeekEnd)
	req, err := http.NewRequestWithContext(ctx, http.MethodGet, url, nil)
	if err != nil {
		return err
	}
	req.Header.Set("User-Agent", "reflopd")
	if off > 0 {
		req.Header.Set("Range", fmt.Sprintf("bytes=%d-", off))
	}
	resp, err := httpClient.Do(req)
	if err != nil {
		return err
	}
	defer resp.Body.Close()
	switch {
	case resp.StatusCode == http.StatusPartialContent && off > 0:
	case resp.StatusCode == http.StatusOK:
		if err := f.Truncate(0); err != nil {
			return err
		}
		if _, err := f.Seek(0, io.SeekStart); err != nil {
			return err
		}
	case resp.StatusCode == http.StatusRequestedRangeNotSatisfiable:
		return nil
	default:
		return fmt.Errorf("HTTP %d", resp.StatusCode)
	}
	_, err = io.Copy(f, resp.Body)
	return err
}

func hashMatches(path, want string) (bool, string) {
	f, err := os.Open(path)
	if err != nil {
		return false, ""
	}
	defer f.Close()
	h := sha256.New()
	if _, err := io.Copy(h, f); err != nil {
		return false, ""
	}
	got := hex.EncodeToString(h.Sum(nil))
	return got == want, got
}

// safeJoin joins name under root and rejects escapes.
func safeJoin(root, name string) (string, error) {
	clean := path.Clean("/" + strings.ReplaceAll(name, "\\", "/"))
	if strings.Contains(name, "\x00") || clean == "/" {
		return "", fmt.Errorf("invalid archive path %q", name)
	}
	p := filepath.Join(root, filepath.FromSlash(clean))
	if !strings.HasPrefix(p, filepath.Clean(root)+string(os.PathSeparator)) {
		return "", fmt.Errorf("archive path escapes target: %q", name)
	}
	return p, nil
}

func untarGz(file, dst string) error {
	f, err := os.Open(file)
	if err != nil {
		return err
	}
	defer f.Close()
	zr, err := gzip.NewReader(f)
	if err != nil {
		return err
	}
	tr := tar.NewReader(zr)
	for {
		h, err := tr.Next()
		if errors.Is(err, io.EOF) {
			return nil
		}
		if err != nil {
			return err
		}
		p, err := safeJoin(dst, h.Name)
		if err != nil {
			return err
		}
		switch h.Typeflag {
		case tar.TypeDir:
			if err := os.MkdirAll(p, 0o755); err != nil {
				return err
			}
		case tar.TypeReg:
			if err := os.MkdirAll(filepath.Dir(p), 0o755); err != nil {
				return err
			}
			if err := writeFile(p, tr, os.FileMode(h.Mode)&0o755|0o644); err != nil {
				return err
			}
		case tar.TypeSymlink:
			// Only relative links that stay inside the tree.
			if filepath.IsAbs(h.Linkname) {
				return fmt.Errorf("absolute symlink %q in archive", h.Name)
			}
			target := filepath.Join(filepath.Dir(p), h.Linkname)
			if !strings.HasPrefix(target, filepath.Clean(dst)+string(os.PathSeparator)) {
				return fmt.Errorf("symlink %q escapes target", h.Name)
			}
			if err := os.MkdirAll(filepath.Dir(p), 0o755); err != nil {
				return err
			}
			os.Remove(p)
			if err := os.Symlink(h.Linkname, p); err != nil {
				return err
			}
		default:
			// Hard links, devices, FIFOs: not expected in python-build-standalone.
			return fmt.Errorf("unsupported entry type %c for %q", h.Typeflag, h.Name)
		}
	}
}

func writeFile(p string, r io.Reader, mode os.FileMode) error {
	f, err := os.OpenFile(p, os.O_CREATE|os.O_TRUNC|os.O_WRONLY, mode)
	if err != nil {
		return err
	}
	if _, err := io.Copy(f, r); err != nil {
		f.Close()
		return err
	}
	return f.Close()
}

// unzipWheel installs a wheel per the binary distribution format:
// <pkg>.data/{purelib,platlib} go to site-packages, scripts to bin/, data
// to the prefix; headers are skipped.
func unzipWheel(file, site, prefix string) error {
	zr, err := zip.OpenReader(file)
	if err != nil {
		return err
	}
	defer zr.Close()
	for _, zf := range zr.File {
		name := zf.Name
		dst := site
		if i := strings.Index(name, ".data/"); i > 0 && !strings.Contains(name[:i], "/") {
			rest := name[i+len(".data/"):]
			kind, sub, _ := strings.Cut(rest, "/")
			switch kind {
			case "purelib", "platlib":
				name = sub
			case "scripts":
				dst, name = filepath.Join(prefix, "bin"), sub
			case "data":
				dst, name = prefix, sub
			default:
				continue
			}
		}
		if strings.HasSuffix(name, "/") || name == "" {
			continue
		}
		if zf.Mode()&os.ModeSymlink != 0 {
			return fmt.Errorf("symlink %q in wheel", zf.Name)
		}
		p, err := safeJoin(dst, name)
		if err != nil {
			return err
		}
		if err := os.MkdirAll(filepath.Dir(p), 0o755); err != nil {
			return err
		}
		rc, err := zf.Open()
		if err != nil {
			return err
		}
		mode := os.FileMode(0o644)
		if zf.Mode()&0o111 != 0 {
			mode = 0o755
		}
		err = writeFile(p, rc, mode)
		rc.Close()
		if err != nil {
			return err
		}
	}
	return nil
}

func copyWorker(site string) error {
	w := server.Worker()
	return fs.WalkDir(w, ".", func(p string, d fs.DirEntry, err error) error {
		if err != nil {
			return err
		}
		if strings.Contains(p, "__pycache__") || strings.HasSuffix(p, ".pyc") {
			if d.IsDir() {
				return fs.SkipDir
			}
			return nil
		}
		dst := filepath.Join(site, filepath.FromSlash(p))
		if d.IsDir() {
			return os.MkdirAll(dst, 0o755)
		}
		b, err := fs.ReadFile(w, p)
		if err != nil {
			return err
		}
		return os.WriteFile(dst, b, 0o644)
	})
}

func makeReadOnly(dir string) error {
	var dirs []string
	err := filepath.WalkDir(dir, func(p string, d fs.DirEntry, err error) error {
		if err != nil {
			return err
		}
		if d.Type()&fs.ModeSymlink != 0 {
			return nil
		}
		if d.IsDir() {
			dirs = append(dirs, p)
			return nil
		}
		info, err := d.Info()
		if err != nil {
			return err
		}
		return os.Chmod(p, info.Mode().Perm()&^0o222)
	})
	if err != nil {
		return err
	}
	for i := len(dirs) - 1; i >= 0; i-- {
		if err := os.Chmod(dirs[i], 0o555); err != nil {
			return err
		}
	}
	return nil
}
